import {items as n, upstream as u, step, path} from "./chain-data.js";

function company(id, title, category, refs, stages, note = "") {
  const steps=stages.map(stage=>Array.isArray(stage)?step(...stage.slice(0,3),id,stage[3]??refs[0],stage[4]):stage);
  return path(id,title,category,refs,steps,note,{company:true});
}

